func (s *Service) claimPeriod(sub store.Subscription, f func(*store.Subscription)) (store.Subscription, bool, error) {
	out, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		if x.Status == store.Canceled || !x.CurrentPeriodStart.Equal(sub.CurrentPeriodStart) || !x.CurrentPeriodEnd.Equal(sub.CurrentPeriodEnd) {
