		x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
	}); err != nil || !ok {
		return false, err
	}
	paid := true
	var err error
	switch {
	case plan.UsageType == store.Metered && sub.Status != store.Trialing:
		paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
	case plan.UsageType == store.Licensed:
		paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
	}
	unavailable := errors.Is(err, payments.ErrUnavailable)
	if err != nil && !unavailable {
		return true, err
	}
	updated, uerr := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		switch {
		case x.Status == store.Canceled, unavailable:
			// Canceled meanwhile, or the charge did not reach the gateway: the status stays.
		case paid:
			x.Status = store.Active
		default:
			x.Status = store.PastDue
		}
		return nil
	})
	if uerr != nil {
		return true, uerr
	}
	s.publish(ctx, updated.OrgID, "subscription.updated", updated)
	return true, err
}

