		t.Fatalf("invoices = %d, want the first and one renewal", len(invs))
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 {
		t.Fatalf("charges = %d, want the first and one renewal", len(cs))
	}
}

func TestGatewayDownStillMovesThePeriodOn(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	sub := subscribeWithCard(t, e, "jane@example.com", "pm_card_visa")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, sub.CustomerID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_gateway_down"; return nil })
	e.Clock.Set(sub.CurrentPeriodEnd)

	n, err := e.Subs.RenewDue(ctx)
	if n != 1 || !errors.Is(err, payments.ErrUnavailable) {
		t.Fatalf("RenewDue = %d, %v; want 1 and ErrUnavailable", n, err)
	}
	next := e.Clock.Now()
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if got.Status != store.Active || !got.CurrentPeriodStart.Equal(next) || !got.CurrentPeriodEnd.Equal(next.AddDate(0, 1, 0)) {
		t.Fatalf("after the outage = %+v", got)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 || invs[1].Status != store.InvoiceOpen {
		t.Fatalf("invoices = %+v, want the renewal open", invs)
	}

	if n, err := e.Subs.RenewDue(ctx); n != 0 || err != nil {
		t.Fatalf("second RenewDue = %d, %v", n, err)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 2 {
		t.Fatalf("the period was invoiced again: %d invoices", len(invs))
	}
	if calls := e.Gateway.Calls(); len(calls) != 2 {
		t.Fatalf("gateway calls = %d, want the first charge and the one that failed", len(calls))
	}
}

