// restorePeriod sets the subscription's period back to the one sub was read in, but only while it is still the period
// [start, end) that renew claimed.
func (s *Service) restorePeriod(sub store.Subscription, start, end time.Time) error {
	_, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		if x.CurrentPeriodStart.Equal(start) && x.CurrentPeriodEnd.Equal(end) {
			x.CurrentPeriodStart, x.CurrentPeriodEnd = sub.CurrentPeriodStart, sub.CurrentPeriodEnd
		}
		return nil
	})
	return err
}

