func TestFailedInvoiceIsRetriedByTheNextRun(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	sub := subscribeWithCard(t, e, "jane@example.com", "pm_card_visa")
	// A discount over 100 percent makes CreateInvoice fail before anything is invoiced; the gateway is not reached.
	_, _ = e.Store.UpdateSubscription(e.Acme.ID, sub.ID, func(x *store.Subscription) error { x.DiscountPercent = 150; return nil })
	e.Clock.Set(sub.CurrentPeriodEnd)

	n, err := e.Subs.RenewDue(ctx)
	if n != 0 || err == nil || errors.Is(err, payments.ErrUnavailable) {
		t.Fatalf("RenewDue = %d, %v; want 0 and a non-gateway error", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if !got.CurrentPeriodStart.Equal(sub.CurrentPeriodStart) || !got.CurrentPeriodEnd.Equal(sub.CurrentPeriodEnd) {
		t.Fatalf("the period moved though nothing was invoiced: %+v", got)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 1 {
		t.Fatalf("invoices = %d, want only the first", len(invs))
	}

	_, _ = e.Store.UpdateSubscription(e.Acme.ID, sub.ID, func(x *store.Subscription) error { x.DiscountPercent = 0; return nil })
	next := e.Clock.Now()
	if n, err := e.Subs.RenewDue(ctx); n != 1 || err != nil {
		t.Fatalf("second RenewDue = %d, %v; want 1 and no error", n, err)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 || invs[1].Status != store.InvoicePaid || invs[1].PeriodStart == nil || !invs[1].PeriodStart.Equal(next) {
		t.Fatalf("invoices = %+v, want the period invoiced once and paid", invs)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 {
		t.Fatalf("charges = %d, want the first and one renewal", len(cs))
	}
}

