247	func (s *Store) CreateInvoice(inv Invoice, now time.Time) (Invoice, error) {
248		if !inv.Currency.Valid() {
249			return Invoice{}, invalid("unknown currency %q", inv.Currency)
250		}
251		if inv.DiscountPercent < 0 || inv.DiscountPercent > 100 {
252			return Invoice{}, invalid("the discount is 0 to 100 percent")
253		}
254		for _, l := range inv.Lines {
255			if l.Quantity <= 0 {
256				return Invoice{}, invalid("a line needs a positive quantity")
257			}
258		}
259		s.mu.Lock()
260		defer s.mu.Unlock()
261		org, ok := s.orgs[inv.OrgID]
262		if !ok {
263			return Invoice{}, ErrNotFound
264		}
265		if inv.SubscriptionID != "" && inv.PeriodStart != nil {
266			for _, o := range s.invoices {
267				if o.OrgID == inv.OrgID && o.SubscriptionID == inv.SubscriptionID && o.PeriodStart != nil && o.PeriodStart.Equal(*inv.PeriodStart) {
268					return Invoice{}, fmt.Errorf("%w: the subscription's period is already invoiced", ErrConflict)
269				}
270			}
271		}
272		c, ok := s.customers[inv.CustomerID]
273		if !ok {
274			return Invoice{}, ErrNotFound
275		}
276		if c.OrgID != inv.OrgID {
277			return Invoice{}, ErrCustomerOrgMismatch
278		}
279		inv.ID = s.newID("in")
280		inv.TaxRateBP = org.TaxRateBP
281		inv.Status = InvoiceOpen
282		inv.CreatedAt = now.UTC()
283		inv.PaidAt, inv.VoidedAt = nil, nil
284		inv = copyInvoice(inv)
285		s.invoices[inv.ID] = inv
286		return copyInvoice(inv), nil
287	}
